import{c as t,W as a,j as r,n as o}from"./chunks/framework.DBclLOWj.js";const u=JSON.parse('{"title":"Keeping the Record","description":"","frontmatter":{"id":"guide.keeping-the-record","title":"Keeping the Record","describes":["proposal.0001"]},"headers":[],"relativePath":"guides/keeping-the-record.md","filePath":"guides/keeping-the-record.md"}'),i={name:"guides/keeping-the-record.md"};function s(n,e,c,d,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="keeping-the-record" tabindex="-1">Keeping the Record <a class="header-anchor" href="#keeping-the-record" aria-label="Permalink to “Keeping the Record”">​</a></h1><h2 id="when-does-something-become-a-policy-a-decision-or-neither" tabindex="-1">When does something become a policy, a decision, or neither? <a class="header-anchor" href="#when-does-something-become-a-policy-a-decision-or-neither" aria-label="Permalink to “When does something become a policy, a decision, or neither?”">​</a></h2><p>The record preserves project knowledge that must survive the proposal which revealed it. It is not a place to restate a feature, capture temporary implementation notes, or collect every review comment.</p><h2 id="the-durable-artifacts" tabindex="-1">The durable artifacts <a class="header-anchor" href="#the-durable-artifacts" aria-label="Permalink to “The durable artifacts”">​</a></h2><table tabindex="0"><thead><tr><th>Artifact</th><th>Purpose</th><th>When to update it</th></tr></thead><tbody><tr><td><a href="./../VISION">Vision</a></td><td>What the project is, its MVP, principles, and direction.</td><td>At completion, when accepted work changes the project&#39;s capabilities, MVP, or direction.</td></tr><tr><td>Policy</td><td>A rule that future work must keep enforcing.</td><td>When completed work establishes a durable constraint.</td></tr><tr><td>Decision</td><td>An architectural choice future work must understand.</td><td>When completed work establishes a durable choice and its rationale.</td></tr></tbody></table><p>The vision is living. Policies and decisions preserve a specific rule or choice with the proposal that established it. A proposal is still the specification for its own change; the record does not replace it.</p><h2 id="apply-the-test" tabindex="-1">Apply the test <a class="header-anchor" href="#apply-the-test" aria-label="Permalink to “Apply the test”">​</a></h2><p>Ask which sentence describes the knowledge:</p><table tabindex="0"><thead><tr><th>If it says</th><th>Put it in</th></tr></thead><tbody><tr><td>“Always do X” or “Never do X.”</td><td>A policy.</td></tr><tr><td>“We chose X over Y because Z.”</td><td>A decision.</td></tr><tr><td>“This change will do X.”</td><td>The current proposal.</td></tr></tbody></table><p><strong>If it does not outlive the current proposal, it belongs in the proposal and nowhere else.</strong> That includes one-off trade-offs, implementation sequencing, review discussion, and notes useful only while this change is in flight. Do not turn the record into a junk drawer.</p><p>A policy constrains future work. State it as an imperative rule that an author can apply without reconstructing the pull request. A decision explains a choice, its alternatives, and the context that made the choice worth keeping. It must answer a future reader who asks why the project works this way.</p><h2 id="prefer-a-check-to-a-policy" tabindex="-1">Prefer a check to a policy <a class="header-anchor" href="#prefer-a-check-to-a-policy" aria-label="Permalink to “Prefer a check to a policy”">​</a></h2><p>Before writing a policy, try to make the rule a validator rule, CI step, git hook, task, or template section. A policy that can be a check <strong>must</strong> be a check. Prose is the enforcement tier most likely to be missed and the prose policies are the ones that rot.</p><p>This repository supplies a concrete example. The <code>.agents/templates/PROPOSAL.md</code> has a “Policies and decisions checked” section. That makes reviewing the current record part of the proposal&#39;s shape, rather than creating a policy that says “remember to check policies.” The template is stronger than a reminder.</p><p>Use the <code>.agents/rules/enforcement-hierarchy.md</code> before adding a rule. Where a check already enforces one, do not duplicate it in prose.</p><h2 id="create-a-durable-entry-only-after-it-is-earned" tabindex="-1">Create a durable entry only after it is earned <a class="header-anchor" href="#create-a-durable-entry-only-after-it-is-earned" aria-label="Permalink to “Create a durable entry only after it is earned”">​</a></h2><p><code>policies/</code> and <code>decisions/</code> start empty on purpose. Do not write speculative policies or decisions because a future change might need them. Record a rule or choice when a feature has established it, and link it to that feature with <code>established-by</code>.</p><p>Use the canonical <code>.agents/templates/POLICY.md</code> for a narrow rule and its enforcement tier. Use the <code>.agents/templates/DECISION.md</code> for the context, choice, alternatives, and consequences. Number either file as <code>&lt;NNNN&gt;-&lt;slug&gt;.md</code> and use the matching <code>policy.&lt;NNNN&gt;</code> or <code>decision.&lt;NNNN&gt;</code> ID.</p><p>The policy lifecycle is <code>draft</code> to <code>active</code>; the decision lifecycle is <code>proposed</code> to <code>accepted</code>. Both can become <code>superseded</code>. The human decides whether the feature&#39;s outcome merits the record; you can ask the agent to write the entry after that decision.</p><h2 id="supersede-do-not-rewrite-history" tabindex="-1">Supersede; do not rewrite history <a class="header-anchor" href="#supersede-do-not-rewrite-history" aria-label="Permalink to “Supersede; do not rewrite history”">​</a></h2><p>Never edit a policy or decision into a different meaning. Never delete one. Write a new entry with <code>supersedes: [&lt;old id&gt;]</code>, then set the old entry&#39;s <code>status: superseded</code>.</p><p>The validator requires both halves of that change and rejects supersession cycles. Superseded entries stay reachable in the documentation site&#39;s collapsed group. That history lets future work understand which rule or choice applied at the time and what replaced it.</p><p>A correction that leaves the meaning intact can be an ordinary revision. When the substantive rule or choice changes, supersede it instead.</p><h2 id="keep-the-vision-current" tabindex="-1">Keep the vision current <a class="header-anchor" href="#keep-the-vision-current" aria-label="Permalink to “Keep the vision current”">​</a></h2><p>At completion, compare accepted work with <code>VISION.md</code>. Update the vision when the work changed what the project is, its capabilities, its MVP, or its direction. Bump <code>updated</code> whenever you change the document, and add substantive changes to its revision history.</p><p>Do not use the vision as a release plan or a feature inventory. It guides proposals across time; the proposal records the individual change.</p><h2 id="before-you-record-it" tabindex="-1">Before you record it <a class="header-anchor" href="#before-you-record-it" aria-label="Permalink to “Before you record it”">​</a></h2><ol><li>State the knowledge in one sentence.</li><li>Apply the outlives-the-proposal test.</li><li>For a rule, try a check, task, or template before prose.</li><li>If it is durable, settle it with the agent, then have the entry written and linked to the proposal that established it.</li><li>At completion, update the vision if accepted work changed it.</li></ol><p>For the surrounding feature flow, see <a href="./running-a-feature">Running a Feature</a>.</p>',29)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
